css:
/* Sage / Forest & Porcelain — Full-Bleed Zero-Margin 1080p Cinema Stage UI (Zero blur filters, GPU-only transitions) */

*{box-sizing:border-box;margin:0;padding:0}
html,body{width:100vw;height:100vh;margin:0;padding:0;overflow:hidden;background:#0D1612;color:#EFF5F1;font-family:"SamsungOne",-apple-system,BlinkMacSystemFont,"Segoe UI","Roboto","Helvetica Neue",Arial,sans-serif;-webkit-font-smoothing:antialiased;user-select:none}
#backdrop{position:fixed;top:0;left:0;width:100vw;height:100vh;background:#0D1612 center/cover no-repeat;overflow:hidden;pointer-events:none;z-index:0}
.bd-layer{position:absolute;top:0;left:0;right:0;bottom:0;display:none}
#root{position:fixed;top:0;left:0;width:1920px;height:1080px;padding:0;display:flex;flex-direction:column;overflow:hidden;transform-origin:0 0;z-index:1}
h1{font-size:52px;font-weight:800;line-height:1.05;letter-spacing:-.8px}
h2{font-size:19px;font-weight:700;padding:0 64px;margin:0 0 16px;letter-spacing:1.4px;text-transform:uppercase;color:#9EB4A6}
.row-active>h2{color:#EFF5F1}
.muted{color:#9EB4A6}
.brand{display:flex;align-items:center;gap:14px;font-size:26px;font-weight:700;letter-spacing:-.2px;color:#EFF5F1}
.brand i{width:34px;height:34px;border-radius:10px;background:#B4D2BD;display:inline-block;box-shadow:inset 0 0 0 8px #1F4233}
.top{display:flex;justify-content:space-between;align-items:center;padding:26px 64px 12px;margin-bottom:0;height:74px;flex:0 0 74px}
.glass{background:rgba(19,32,26,.94);border:1px solid rgba(180,210,189,.16);border-radius:18px}

/* Hardware-only transform transitions (120ms, zero box-shadow animation) */
.focusable{outline:none;transition:transform .12s cubic-bezier(.2,1,.3,1),border-color .12s ease,background-color .12s ease}
.focusable.focused{transform:translate3d(0,-4px,0) scale(1.04);border-color:#B4D2BD!important;box-shadow:0 0 0 3px #B4D2BD;z-index:4}

.btn{display:inline-flex;align-items:center;gap:12px;height:54px;padding:0 32px;border-radius:27px;font-size:20px;font-weight:600;background:rgba(24,40,32,.92);color:#EFF5F1;border:1.5px solid rgba(180,210,189,.16)}
.btn.primary{background:#B4D2BD;color:#102D20;border-color:#B4D2BD;font-weight:700}
.btn.focused{transform:translate3d(0,-2px,0) scale(1.03)}

/* Full-Bleed Split Stage Hero with Generous Internal Padding */
.hero{width:100%;height:350px;padding:22px 64px 28px;margin-bottom:8px;position:relative;display:flex;flex-direction:column;justify-content:center;flex:0 0 350px}
.hero-body{max-width:1120px}
.hero-eyebrow{font-size:15px;font-weight:700;letter-spacing:2.2px;text-transform:uppercase;color:#B4D2BD;margin-bottom:8px}
.hero-title{font-size:56px;font-weight:800;line-height:1.05;letter-spacing:-1px;color:#EFF5F1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.meta{display:flex;align-items:center;flex-wrap:wrap;gap:0;font-size:19px;font-weight:500;color:#9EB4A6;margin-top:10px}
.meta span{padding:0;background:none;border:none;border-radius:0}
.meta span+span::before{content:"\00a0\00b7\00a0\00a0";color:#7A9685}
.hero-desc{max-width:920px;font-size:20px;line-height:1.48;color:#9EB4A6;margin:12px 0 18px;max-height:60px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}

/* Full-screen vertical shelf stage */
.rows{flex:1 1 auto;min-height:0;height:656px;overflow:hidden;position:relative}
.rows-inner{position:relative;transition:transform .15s cubic-bezier(.2,1,.3,1);will-change:transform}
#regional-rows{position:relative}
.row{margin-bottom:36px;position:relative;transition:opacity .15s ease}
.row.row-above{opacity:0;pointer-events:none}
.row.row-active{opacity:1}
.row.row-next{opacity:.92}
.row.row-far{opacity:.78}

.track{display:flex;gap:28px;position:relative;margin:0;padding:12px 64px 22px 64px;transition:transform .14s cubic-bezier(.2,1,.3,1);will-change:transform}

/* Pure Artwork Cards — zero bottom text banner clutter */
.card{flex:0 0 auto;width:210px;border-radius:18px;overflow:hidden;background:#13201A;border:2px solid rgba(255,255,255,.08);position:relative}
.card .art{width:210px;height:315px;background:#1D2F26 center/cover no-repeat}
.card.wide{width:372px}
.card.wide .art{width:372px;height:210px}
.card:not(.ep-card)>.t,.rank-poster>.t{font-size:0;line-height:0;height:0;padding:0;margin:0;opacity:0;overflow:hidden;border:0}
.prog{position:absolute;left:0;right:0;bottom:0;height:5px;background:rgba(255,255,255,.2);z-index:3}
.prog b{display:block;height:100%;background:#B4D2BD}

/* Sleek Horizontal Streaming Platform Pills */
.chip{flex:0 0 auto;height:68px;min-width:184px;padding:0 28px 0 14px;border-radius:34px;display:flex;flex-direction:row;align-items:center;justify-content:flex-start;gap:16px;background:rgba(21,36,27,.92);border:1.5px solid rgba(180,210,189,.16)}
.chip .cn{font-size:20px;font-weight:600;color:#EFF5F1;white-space:nowrap}
.logo{display:inline-flex;align-items:center;justify-content:center;border-radius:22px;flex:0 0 auto}
.logo.mono{background:#B4D2BD;color:#102D20;font-weight:700;font-size:20px}
.plogo .logo{border-radius:26px}
.plogo .logo.mono{font-size:42px}

.filters{display:flex;align-items:center;gap:14px;padding:8px 64px 14px;margin-bottom:6px}
.pill{height:48px;padding:0 26px;border-radius:24px;font-size:19px;font-weight:600;display:flex;align-items:center;background:rgba(21,36,27,.92);border:1.5px solid rgba(180,210,189,.16);color:#9EB4A6}
.pill.on{background:#1F4233;color:#B4D2BD;border-color:#B4D2BD}
.pill-sep{width:1px;height:26px;background:rgba(180,210,189,.16);margin:0 8px;flex:0 0 1px}

/* Quick Connect Sign-In */
.code{display:flex;gap:16px;margin:28px 0}
.code span{width:104px;height:132px;border-radius:20px;background:#13201A;border:2px solid #B4D2BD;font-size:78px;font-weight:700;display:flex;align-items:center;justify-content:center;color:#B4D2BD}
.signin{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:1080px;padding:58px 70px;text-align:left}
.steps{font-size:23px;line-height:1.6;color:#9EB4A6}.steps b{color:#EFF5F1}

/* Thoughtful, Clutter-Free Split-Stage Detail Screen (Single Active Tab Shelf) */
.detail{display:flex;justify-content:space-between;align-items:flex-start;gap:56px;width:100%;padding:18px 64px 22px;margin-bottom:4px}
.detail-main{flex:1;min-width:0;max-width:1120px}
.detail h1{font-size:56px;line-height:1.05}
.detail p{font-size:20px;line-height:1.48;color:#9EB4A6;margin:12px 0 12px;max-width:960px;max-height:60px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.detail-credits{font-size:18px;color:#9EB4A6;margin:0 0 22px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.detail-credits b{color:#EFF5F1;font-weight:600}
.detail-art-card{width:440px;height:248px;border-radius:22px;background:#13201A center/cover no-repeat;border:1.5px solid rgba(180,210,189,.16);flex:0 0 auto;position:relative;overflow:hidden;box-shadow:0 20px 44px rgba(0,0,0,.5)}
.detail-art-card::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,22,18,0) 50%,rgba(13,22,18,.78) 100%);pointer-events:none}
.detail-art-label{position:absolute;left:18px;bottom:16px;z-index:2;font-size:14px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#B4D2BD;background:rgba(13,22,18,.86);padding:6px 14px;border-radius:10px;border:1px solid rgba(180,210,189,.16)}
.actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.detail-tab-hidden{opacity:0!important;max-height:0!important;margin:0!important;padding:0!important;overflow:hidden!important;pointer-events:none!important}

/* Sleek 16:9 Overlay Episode Cards & Generously Padded Inline Editorial Synopsis Bar */
.ep-preview{display:flex;align-items:baseline;gap:18px;width:100%;padding:10px 64px 14px;margin:0 0 6px;background:transparent;border:none;border-bottom:1px solid rgba(180,210,189,.12)}
.ep-prev-head{display:flex;align-items:baseline;gap:14px;flex:0 0 auto}
.ep-prev-tag{font-size:20px;font-weight:700;color:#B4D2BD}
.ep-prev-meta{font-size:16px;font-weight:600;color:#9EB4A6}
.ep-prev-desc{font-size:18px;line-height:1.4;color:#9EB4A6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;min-width:0}

.ep-card{width:372px;height:210px;border-radius:18px;position:relative;overflow:hidden;background:#13201A}
.ep-card .art{width:372px;height:210px;position:relative;background:#1D2F26 center/cover no-repeat}
.ep-badge{position:absolute;top:14px;left:14px;padding:5px 12px;border-radius:9px;font-size:13px;font-weight:700;letter-spacing:.7px;text-transform:uppercase;background:#B4D2BD;color:#102D20;z-index:2}
.ep-badge.watched{background:rgba(16,27,23,.9);color:#B4D2BD;border:1px solid #B4D2BD}
.ep-runtime{position:absolute;top:14px;right:14px;padding:5px 11px;border-radius:8px;font-size:13px;font-weight:600;background:rgba(13,22,18,.88);color:#9EB4A6;z-index:2}
.ep-info{position:absolute;left:0;right:0;bottom:0;padding:42px 20px 16px;background:linear-gradient(180deg,rgba(13,22,18,0) 0%,rgba(13,22,18,.88) 48%,rgba(13,22,18,.98) 100%);z-index:2}
.ep-title{font-size:19px;font-weight:700;color:#EFF5F1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:10px}
.ep-num{display:inline-flex;align-items:center;justify-content:center;padding:3px 9px;border-radius:7px;font-size:13px;font-weight:800;background:#1F4233;color:#B4D2BD;flex:0 0 auto}
.ep-sub{font-size:14px;line-height:1.35;color:#9EB4A6;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.88}

/* Cast & Crew Minimal Pills */
.person-card{flex:0 0 auto;width:188px;padding:18px 16px;border-radius:18px;background:rgba(19,32,26,.92);border:1.5px solid rgba(180,210,189,.16);display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px}
.person-avatar{width:88px;height:88px;border-radius:44px;background:#1F4233 center/cover no-repeat;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700;color:#B4D2BD;margin-bottom:4px}
.p-name{font-size:18px;font-weight:600;color:#EFF5F1;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.p-role{font-size:14px;color:#9EB4A6;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* Top 10 Trending Today — Clean Minimalist Number + Pure Poster */
.card.rank-card{width:262px;display:flex;align-items:flex-end;background:transparent;border:none!important;box-shadow:none!important;overflow:visible;position:relative;padding-left:52px}
.card.rank-card.focused{transform:translate3d(0,-4px,0) scale(1.04);box-shadow:none!important}
.rank-num{position:absolute;left:-2px;bottom:8px;width:68px;text-align:right;padding-right:6px;font-size:120px;font-weight:900;line-height:.82;letter-spacing:-6px;color:rgba(19,32,26,.95);-webkit-text-stroke:2.5px #7A9685;pointer-events:none;z-index:1}
.card.rank-card.focused .rank-num{color:#B4D2BD;-webkit-text-stroke:0}
.rank-poster{width:210px;border-radius:18px;overflow:hidden;background:#13201A;border:2px solid rgba(255,255,255,.08);position:relative;z-index:2}
.card.rank-card.focused .rank-poster{border-color:#B4D2BD;box-shadow:0 0 0 3px #B4D2BD}
.rank-poster .art{width:210px;height:315px;position:relative}
.rank-badge{font-size:0;line-height:0;padding:0;border:0;opacity:0;pointer-events:none;position:absolute}
.nextup-card .art{position:relative}

/* Search, Pro Cinema Player & Modals */
.searchbox{height:68px;width:960px;border-radius:34px;padding:0 32px;margin:8px 64px 18px;font-size:26px;display:flex;align-items:center}
.keys{display:grid;grid-template-columns:repeat(13,68px);gap:10px;padding:0 64px;margin-bottom:24px}
.key{height:54px;border-radius:12px;background:#13201A;border:1.5px solid rgba(180,210,189,.16);display:flex;align-items:center;justify-content:center;font-size:21px;font-weight:600}
.key.w2{grid-column:span 2}

/* Modern, Sleek, Full-Bleed Cinema Media Player */
#player{position:fixed;top:0;left:0;width:100vw;height:100vh;background:#000;z-index:25;overflow:hidden}
#player video,#player object{width:100%;height:100%;object-fit:contain;background:#000;transition:transform .18s ease}
#player video.fit-contain{object-fit:contain}
#player video.fit-cover{object-fit:cover}
#player video.fit-fill{object-fit:fill}
video::cue{background:rgba(10,18,14,.84);color:#F4F1EA;font-size:38px;font-weight:600;text-shadow:0 2px 6px rgba(0,0,0,.9)}

.player-top{position:absolute;top:0;left:0;right:0;padding:38px 64px 54px;background:linear-gradient(180deg,rgba(8,14,11,.94) 0%,rgba(8,14,11,.52) 58%,rgba(8,14,11,0) 100%);display:flex;justify-content:space-between;align-items:flex-start;transition:opacity .22s ease;pointer-events:none;z-index:2}
.player-top.hide{opacity:0}
.player-eyebrow{font-size:15px;font-weight:700;letter-spacing:2.2px;text-transform:uppercase;color:#B4D2BD}
.player-title{font-size:38px;font-weight:800;line-height:1.1;letter-spacing:-.5px;color:#EFF5F1;margin-top:6px}
.player-badges{display:flex;align-items:center;gap:12px}
.p-badge{padding:7px 16px;border-radius:999px;font-size:14px;font-weight:700;letter-spacing:1.1px;text-transform:uppercase;background:rgba(19,32,26,.88);border:1.5px solid rgba(180,210,189,.16);color:#9EB4A6}
.p-badge.accent{background:rgba(31,66,51,.92);border-color:#B4D2BD;color:#B4D2BD}

.player-hud{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%);padding:18px 34px;border-radius:999px;background:rgba(13,22,18,.92);border:1.5px solid rgba(180,210,189,.32);font-size:24px;font-weight:700;color:#EFF5F1;display:none;align-items:center;justify-content:center;gap:12px;z-index:4;pointer-events:none;box-shadow:0 16px 40px rgba(0,0,0,.6)}
.player-hud.icon-only{width:96px;height:96px;padding:0;border-radius:48px;font-size:36px;color:#B4D2BD}

.osd{position:absolute;left:0;right:0;bottom:0;padding:56px 64px 42px;background:linear-gradient(180deg,rgba(8,14,11,0) 0%,rgba(8,14,11,.82) 36%,rgba(8,14,11,.98) 100%);border:none;border-radius:0;transition:opacity .22s ease;z-index:2}
.osd.hide{opacity:0;pointer-events:none}
.time-rem{font-size:19px;font-weight:600;color:#9EB4A6;margin-left:14px}

.osd .bar{height:10px;border-radius:5px;background:rgba(255,255,255,.16);margin:0 0 22px;position:relative}
.pb-buf{position:absolute;left:0;top:0;bottom:0;border-radius:5px;background:rgba(180,210,189,.28);pointer-events:none;z-index:1}
.osd .bar b{display:block;height:100%;border-radius:5px;background:#B4D2BD;position:relative;min-width:10px;z-index:2}
.pb-thumb{width:22px;height:22px;border-radius:50%;background:#EFF5F1;border:4px solid #B4D2BD;position:absolute;right:-11px;top:-6px;box-shadow:0 2px 10px rgba(0,0,0,.65)}

.osd .row2{display:flex;justify-content:space-between;align-items:center;font-size:20px;color:#9EB4A6}
.time-group{display:flex;align-items:baseline;gap:10px;font-variant-numeric:tabular-nums}
.time-cur{font-size:24px;font-weight:700;color:#EFF5F1}
.time-sep{font-size:20px;color:#7A9685}
.time-tot{font-size:21px;font-weight:600;color:#9EB4A6}
.osd-hints{display:none;align-items:center;gap:12px}
.osd.paused .osd-hints{display:flex}
.hint-pill{display:inline-flex;align-items:center;gap:8px;padding:8px 18px;border-radius:999px;background:rgba(21,36,27,.86);border:1px solid rgba(180,210,189,.16);font-size:17px;font-weight:600;color:#9EB4A6}
.hint-pill b{color:#B4D2BD;font-weight:700}

.buffer{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);padding:18px 32px;border-radius:999px;background:rgba(13,22,18,.94);border:1.5px solid rgba(180,210,189,.16);font-size:22px;font-weight:600;color:#EFF5F1;display:none;align-items:center;gap:14px;z-index:4}

.menu{position:absolute;right:64px;bottom:148px;top:auto;width:520px;max-height:680px;padding:34px 38px;border-radius:24px;background:rgba(15,26,21,.96);border:1.5px solid rgba(180,210,189,.24);box-shadow:0 24px 60px rgba(0,0,0,.68);overflow:hidden;z-index:6}
.menu h2{padding:0;margin:0 0 14px;font-size:17px;letter-spacing:1.6px;color:#B4D2BD}
.opt{height:58px;border-radius:14px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;font-size:21px;font-weight:600;margin-bottom:10px;background:rgba(24,40,32,.6);border:1.5px solid transparent}
.opt.on{background:#1F4233;color:#B4D2BD;border-color:rgba(180,210,189,.3)}
.opt.focused{transform:none;border-color:#B4D2BD!important;box-shadow:0 0 0 3px #B4D2BD}
.fit-row{display:flex;gap:10px;margin-top:4px}
.fit-opt{flex:1;height:48px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:17px;font-weight:600;background:rgba(24,40,32,.6);color:#9EB4A6;border:1.5px solid rgba(180,210,189,.16)}
.fit-opt.on{background:#1F4233;color:#B4D2BD;border-color:#B4D2BD}
.fit-opt.focused{transform:none;border-color:#B4D2BD!important;box-shadow:0 0 0 3px #B4D2BD}

.upnext-card{position:absolute;right:64px;bottom:154px;width:460px;padding:22px 26px;border-radius:22px;background:rgba(15,26,21,.96);border:2px solid #B4D2BD;box-shadow:0 24px 60px rgba(0,0,0,.68);display:none;flex-direction:column;gap:8px;z-index:5}
.upnext-eyebrow{font-size:14px;font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:#B4D2BD}
.upnext-title{font-size:22px;font-weight:700;color:#EFF5F1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.upnext-sub{font-size:16px;font-weight:600;color:#9EB4A6}

#toast{position:fixed;right:64px;bottom:48px;padding:18px 28px;border-radius:16px;background:rgba(19,32,26,.94);border:1.5px solid #B4D2BD;font-size:21px;font-weight:600;opacity:0;transition:opacity .18s ease;z-index:40;pointer-events:none}
#toast.show{opacity:1}
.empty{font-size:22px;color:#9EB4A6;padding:18px 64px}
.state{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:920px;padding:54px 64px}
.state p{font-size:23px;margin:16px 0 28px}
.ver-badge{font-size:15px;font-weight:600;padding:4px 12px;border-radius:999px;background:rgba(255,255,255,.06);color:#9EB4A6}
.btn.has-update{background:#1F4233;color:#B4D2BD;border-color:#B4D2BD}
.ota-banner{margin:0 64px 12px;padding:14px 28px;display:flex;justify-content:space-between;align-items:center;font-size:20px;border-color:#B4D2BD;background:rgba(31,66,51,.94);flex:0 0 auto}
.modal-backdrop{position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(10,16,13,.88);z-index:35;display:flex;align-items:center;justify-content:center}
.modal-card{width:980px;padding:52px 60px}
.ota-status{font-size:22px;line-height:1.45;color:#9EB4A6;margin-top:20px;padding:18px 22px;border-radius:14px;background:#13201A;border:1px solid rgba(180,210,189,.16)}

/* Designed Sage / Forest Shimmer Skeletons & Spinners (GPU opacity + transform only) */
@keyframes skelPulse{0%,100%{opacity:.42}50%{opacity:.92}}
@keyframes spinRing{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}
.skel-pulse{background:linear-gradient(110deg,rgba(22,38,30,.88) 20%,rgba(44,74,59,.94) 50%,rgba(22,38,30,.88) 80%);border:1px solid rgba(180,210,189,.16);animation:skelPulse 1.4s ease-in-out infinite}
.skel-bar{height:18px;border-radius:9px}
.skel-title{height:52px;width:480px;border-radius:14px;margin:10px 0 12px}
.skel-pill{height:54px;width:170px;border-radius:27px;flex:0 0 auto}
.skel-chip{height:68px;width:192px;border-radius:34px;flex:0 0 auto}
.skel-card{flex:0 0 auto;width:210px;height:315px;border-radius:18px}
.skel-card.wide{width:372px;height:210px}
.skel-card.ep{width:372px;height:210px}
.spinner-ring{width:22px;height:22px;border-radius:50%;border:3px solid rgba(180,210,189,.24);border-top-color:#B4D2BD;display:inline-block;animation:spinRing .8s linear infinite;flex:0 0 auto}
.loading-inline{display:inline-flex;align-items:center;gap:12px;font-size:19px;font-weight:600;color:#9EB4A6;padding:4px 64px 12px}
.code span.skel-digit{border-color:rgba(180,210,189,.16);color:transparent}

@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}.focusable.focused{transform:none}}

/* Hold-OK Platform Reorder Mode */
.chip.reordering{transform:translate3d(0,-10px,0) scale(1.08)!important;background:#1F4233!important;border:2.5px solid #B4D2BD!important;box-shadow:0 16px 36px rgba(0,0,0,.68)!important;z-index:10}
.chip-move-hint{margin-left:8px;padding:4px 12px;border-radius:999px;font-size:14px;font-weight:700;letter-spacing:.6px;background:#B4D2BD;color:#102D20;white-space:nowrap}

/* Live Focused Movie/Series Details Panel Underneath More Like This (#similar-row) */
.sim-preview{margin:20px 64px 0;padding:34px 42px;min-height:360px;border-radius:26px;background:linear-gradient(135deg,rgba(19,33,26,.96) 0%,rgba(13,22,18,.94) 100%);border:1.5px solid rgba(180,210,189,.24);box-shadow:0 24px 56px rgba(0,0,0,.55);display:flex;justify-content:space-between;align-items:stretch;gap:48px}
.sim-prev-main{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:space-between}
.sim-prev-top{display:flex;align-items:center;gap:14px;margin-bottom:8px}
.sim-match-pill{padding:5px 14px;border-radius:999px;font-size:13px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;background:#1F4233;color:#B4D2BD;border:1px solid #B4D2BD}
.sim-prev-eyebrow{font-size:15px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#B4D2BD}
.sim-prev-title{font-size:44px;font-weight:800;line-height:1.06;letter-spacing:-.8px;color:#EFF5F1;margin:4px 0 10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sim-prev-specs{display:flex;align-items:center;gap:10px;margin-left:16px}
.sim-spec-badge{padding:3px 10px;border-radius:6px;font-size:13px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;background:rgba(255,255,255,.07);border:1px solid rgba(180,210,189,.16);color:#EFF5F1}
.sim-prev-desc{font-size:21px;line-height:1.48;color:#9EB4A6;margin:14px 0 18px;max-width:1040px;max-height:94px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical}
.sim-prev-footer{display:flex;align-items:center;justify-content:space-between;padding-top:16px;border-top:1px solid rgba(180,210,189,.14);gap:24px}
.sim-prev-credits{font-size:18px;color:#9EB4A6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;min-width:0}
.sim-prev-credits b{color:#EFF5F1;font-weight:600}
.sim-cta-pill{height:46px;padding:0 24px;border-radius:23px;background:#B4D2BD;color:#102D20;font-size:17px;font-weight:700;display:inline-flex;align-items:center;gap:8px;flex:0 0 auto}
.sim-prev-art{width:520px;height:292px;border-radius:20px;background:#1D2F26 center/cover no-repeat;border:1.5px solid rgba(180,210,189,.24);position:relative;overflow:hidden;flex:0 0 520px;box-shadow:0 16px 38px rgba(0,0,0,.52)}
.sim-prev-art::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,22,18,0) 45%,rgba(13,22,18,.84) 100%);pointer-events:none}
.sim-prev-art-tag{position:absolute;left:18px;bottom:16px;z-index:2;padding:6px 14px;border-radius:10px;font-size:14px;font-weight:700;letter-spacing:1px;text-transform:uppercase;background:rgba(13,22,18,.88);border:1px solid rgba(180,210,189,.16);color:#B4D2BD}

.cast-preview{margin:18px 64px 0;padding:26px 36px;min-height:360px;border-radius:26px;background:linear-gradient(135deg,rgba(19,33,26,.96) 0%,rgba(13,22,18,.94) 100%);border:1.5px solid rgba(180,210,189,.24);box-shadow:0 24px 56px rgba(0,0,0,.55);display:flex;flex-direction:column;gap:14px}
.cast-prev-head{display:flex;justify-content:space-between;align-items:center;gap:24px}
.cast-prev-left{display:flex;align-items:center;gap:18px}
.cast-prev-avatar{width:64px;height:64px;border-radius:32px;background:#1F4233 center/cover no-repeat;border:2px solid #B4D2BD;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:800;color:#B4D2BD;flex:0 0 64px}
.cast-prev-title{font-size:32px;font-weight:800;color:#EFF5F1;line-height:1.1}
.cast-prev-sub{font-size:16px;font-weight:600;color:#B4D2BD;letter-spacing:1.2px;text-transform:uppercase;margin-bottom:4px}
.cast-works-track{display:flex;gap:22px;padding:8px 4px 6px;overflow:hidden}
.cast-works-track .card{width:176px}
.cast-works-track .card .art{width:176px;height:256px}
